/**
 * The shared trader and shoulder pet classes of an ejected project (ADR 0098 D1, D4; ADR 0107 D1 to D3; ADR 0109 D2;
 * ADR 0112 D3; eject 2c), generated by `docs/reference/eject/b537b-mob-templates/gen-mob-templates.py` from the
 * runtime's `registry/mob/MobTrader`, `TraderReputation`, `MobShoulder` and `goals/RestockAtWorkSiteGoal`,
 * `PerchOnOwnerGoal`: the runtime's parsed `TraderParser` records become `Trader`'s, the `MsmMob` adapter the generated
 * entity class (`MobTrader.Trading`, `MobShoulder.Pet`) with its synched perch flags, `EventRunner`'s `on_trade` the
 * entity's own event method, and the logger the mod's. The targets tests compare the code lines with the runtime
 * sources. Minecraft 26.3, Mojang names.
 *
 * @packageDocumentation
 */

/** `entity/Trader.java`: the trader records. */
export function traderJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's TraderParser records (loader) as plain records.
package ${entityPackage};

import java.util.List;
import java.util.Optional;
import net.minecraft.resources.Identifier;

/**
 * {@code msm:trader} with every default resolved (ADR 0098 D1, ADR 0107 D1 to D3; the runtime's {@code TraderParser.Trader}).
 * The {@code on_trade} event is the generated entity's own method, handed to {@code MobTrader} on its own.
 *
 * @param tradeSets  one to five levels, level 1 first
 * @param levels     whether trading gives XP and unlocks the next level; without it only level 1 is used
 * @param restock    when offers refill
 * @param tradeSound played at the mob after each trade; empty means {@code minecraft:entity.villager.yes}
 * @param reputation the per-player memory; empty means none
 * @param demand     whether vanilla's demand rule applies to each offer
 * @param workSite   a block id or {@code #}-prefixed block tag the mob restocks at; empty means in place
 */
public record Trader(List<TradeLevel> tradeSets, boolean levels, Restock restock, Optional<Identifier> tradeSound,
        Optional<Reputation> reputation, boolean demand, Optional<String> workSite) {
    /** How far the mob looks for its work site, and how near it restocks (ADR 0107 D3 as amended, B524). */
    public static final int WORK_SITE_RANGE = 16;
    public static final int WORK_SITE_REACH = 2;

    /** When used-up offers refill. */
    public enum Restock {
        /** Twice a day at the mob, with no workstation. */
        TWICE_A_DAY,
        /** Never. */
        NEVER
    }

    /** One trading level: the trade set its offers are drawn from; {@code xpToNext} empty means vanilla's threshold. */
    public record TradeLevel(Identifier tradeSet, Optional<Integer> xpToNext) {}

    /**
     * {@code reputation} (ADR 0107 D1 as amended after the spike): a hit takes {@code hurt}, a trade adds {@code trade}, a
     * gift of {@code giftItem} (an item id or {@code #}-prefixed item tag) adds {@code gift}, a value below 0 recovers
     * {@code decayPerDay} a day; {@code priceStep} empty means 1 divided by each offer's own price multiplier.
     */
    public record Reputation(int hurt, int trade, Optional<String> giftItem, int gift, int decayPerDay, Optional<Integer> priceStep) {
        /** The most trading adds, and the most gifts add (vanilla's caps, B524). */
        public static final int TRADE_CAP = 25;
        public static final int GIFT_CAP = 25;
        /** How far trading value fades each day (vanilla's, B524). */
        public static final int TRADE_DECAY_PER_DAY = 2;
    }

    /** The highest level the mob can reach: the number of levels, or 1 without {@code levels}. */
    public int maxLevel() {
        return levels ? tradeSets.size() : 1;
    }

    /**
     * Trading XP needed to leave {@code level} (1-based), counted from the start: the level's {@code xp_to_next}, else
     * {@code vanillaThreshold}.
     */
    public int xpToLeave(int level, int vanillaThreshold) {
        return tradeSets.get(level - 1).xpToNext().orElse(vanillaThreshold);
    }
}
`;
}

/** `entity/MobTrader.java`: the runtime's `MobTrader`. */
export function mobTraderJava(entityPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MobTrader (registry/mob) as a plain class.
package ${entityPackage};

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.util.RandomSource;
import net.minecraft.util.Unit;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.ExperienceOrb;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.npc.villager.VillagerData;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.MerchantMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.trading.Merchant;
import net.minecraft.world.item.trading.MerchantOffer;
import net.minecraft.world.item.trading.MerchantOffers;
import net.minecraft.world.item.trading.TradeSet;
import net.minecraft.world.item.trading.VillagerTrade;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.level.storage.loot.LootParams;
import net.minecraft.world.level.storage.loot.parameters.LootContextParamSets;
import net.minecraft.world.level.storage.loot.parameters.LootContextParams;
import java.util.function.BiConsumer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Trading (ADR 0098 D1, {@code msm:trader}) on every mob base. Every body is a {@code Merchant} through {@code MsmMob},
 * whose methods delegate here: vanilla's menu treats its merchant as an entity (a shift-click plays the trade sound at
 * it), so the module cannot be the merchant itself. A right click with an empty hand or an item nothing else used first
 * opens the menu ({@code Merchant.openTradingScreen} on the body); vanilla's menu does the paying, the result slot and
 * shift-click trading, and calls {@code #notifyTrade} for each trade. A mob without {@code msm:trader} has no offers.
 *
 * <p>Offers are drawn per level from the level's trade set with vanilla's rules ({@code TradeSet#calculateNumberOfTrades}
 * and {@code VillagerTrade#getOffer} in a {@code VILLAGER_TRADE} loot context with the origin, the mob as this entity
 * and additional costs allowed; B469), saved on the mob with their uses, the trading XP, the level and the last restock.
 * A trade uses the offer, gives the mob trading XP (with {@code levels}) and the player experience orbs (when the offer
 * rewards them), then fires {@code on_trade}; the trade sound plays when the result slot fills (at most once a second)
 * and, on a shift-click, from vanilla's menu. Enough XP raises the level at once and draws the next
 * level's offers; a level-up or restock sends the offers again to an open menu ({@code sendMerchantOffers}). Restocking
 * ({@code twice_a_day}) refills used offers once in each half of the day (clock ticks 0 to 11999 and 12000 to 23999),
 * checked every second while the AI runs and when the menu opens; {@code never} keeps them used up.
 *
 * <p>Babies, mobs with a target (angry), mobs that something rides, {@code monster} mobs at night and a mob already
 * trading with another player do not trade: the click passes on (to {@code msm:on_interact} or vanilla). Vanilla's
 * client shows the XP bar against villager thresholds, so with {@code xp_to_next} the XP sent to the screen is scaled
 * into the vanilla range of the level ({@code #getVillagerXp}); the real XP is {@code #xp()}.
 *
 * <p>Batch 2 of vanilla parity 3 (ADR 0107 D1 to D3 as amended after the B524 spike): with {@code reputation} the mob
 * remembers each player ({@code TraderReputation}): a hit lowers the standing, a trade and a gift of the gift item (a
 * plain use with it, before the menu; at the gift cap the click opens the menu instead) raise it, and every clock day it
 * fades. Each time a player opens the menu the special prices are worked out for that player, and they are reset when
 * the menu closes, so another player sees their own. With {@code demand} (the default) each restock first applies
 * vanilla's demand rule ({@code MerchantOffer.updateDemand} before {@code resetUses}), so heavily used offers cost more
 * until quieter restocks bring them down. With {@code work_site} a due restock only marks the offers as waiting
 * ({@code #restockPending}); the mob's {@code RestockAtWorkSiteGoal}, added on its first server AI step, walks to the
 * nearest such block within 16 blocks and restocks there.
 */
public final class MobTrader {
    /** Save keys (the vanilla villager's names where one exists). */
    static final String OFFERS = "Offers";
    static final String XP = "Xp";
    static final String LEVEL = "TraderLevel";
    static final String RESTOCK = "RestockHalfDay";
    static final String PENDING = "RestockPending";
    /** Clock ticks between two restock chances: two a day. */
    public static final long HALF_DAY = 12000L;
    private static final long UNKNOWN = Long.MIN_VALUE;
    /** Trade sets already warned about, by mob type and set, so a missing set logs once. */
    private static final Set<String> WARNED = ConcurrentHashMap.newKeySet();

    private static final Logger LOGGER = LoggerFactory.getLogger("${modId}");

    /** A trader as the generated entity class is one: the module behind its {@code Merchant} methods. */
    public interface Trading {
        MobTrader mobTrader();
    }

    private final PathfinderMob mob;
    /** {@code base: monster}: no trading at night. */
    private final boolean monster;
    /** The priority of the work site goal: after the fighting goals ({@code MobTaming.afterFighting}). */
    private final int workSitePriority;
    /** Fires the definition's {@code on_trade} event (self the mob, other the player); null without one. */
    private final BiConsumer<ServerLevel, Player> onTrade;
    /** Null without {@code msm:trader}. */
    private final Trader trader;
    private Player tradingPlayer;
    private MerchantOffers offers;
    private int xp;
    private int level = 1;
    private long restockHalfDay = UNKNOWN;
    private int resends;
    private int restocks;
    private int lastTradeSound = -20;
    /** Null without {@code reputation}. */
    private final TraderReputation reputation;
    /** Whether a due restock waits for the work site ({@code work_site} only). */
    private boolean restockPending;
    private RestockAtWorkSiteGoal workSiteGoal;

    /**
     * The trading of {@code mob} ({@code trader} null for none): {@code monster} for a {@code monster} base, the work site
     * goal's priority and the {@code on_trade} event (null without one).
     */
    public MobTrader(PathfinderMob mob, boolean monster, int workSitePriority, Trader trader,
            BiConsumer<ServerLevel, Player> onTrade) {
        this.mob = mob;
        this.monster = monster;
        this.workSitePriority = workSitePriority;
        this.onTrade = onTrade;
        this.trader = trader;
        this.reputation = trader == null ? null : trader.reputation().map(TraderReputation::new).orElse(null);
    }

    /** Whether the mob has {@code msm:trader}. */
    public boolean enabled() {
        return trader != null;
    }

    /** The trading level, 1 to the number of levels. */
    public int traderLevel() {
        return level;
    }

    /** The trading XP counted from the start (0 without {@code levels}). */
    public int xp() {
        return xp;
    }

    /** How often the offers were sent again to an open menu (level-ups and restocks); for the GameTests. */
    public int resends() {
        return resends;
    }

    /** How often the offers were restocked; for the GameTests. */
    public int restocks() {
        return restocks;
    }

    /** The per-player memory ({@code reputation}), or empty without it. */
    public Optional<TraderReputation> reputation() {
        return Optional.ofNullable(reputation);
    }

    /** Whether a due restock waits for the mob to reach its work site ({@code work_site}). */
    public boolean restockPending() {
        return restockPending;
    }

    /** The work site goal once the first server AI step added it, or null; for the GameTests. */
    public RestockAtWorkSiteGoal workSiteGoal() {
        return workSiteGoal;
    }

    private PathfinderMob body() {
        return mob;
    }

    // Opening the menu

    /** The right-click hook of {@code MobDriver#mobInteract}; null passes the click on, as every module does. */
    InteractionResult mobInteract(Player player, InteractionHand hand) {
        if (trader == null) {
            return null;
        }
        PathfinderMob body = body();
        if (!(body.level() instanceof ServerLevel server)) {
            // The client cannot see targets, offers or the time of night; it only answers the arm swing.
            return body.isBaby() || body.isVehicle() ? null : InteractionResult.SUCCESS;
        }
        InteractionResult gift = takeGift(server, player, hand);
        if (gift != null) {
            return gift;
        }
        if (refusal(player, server.isDarkOutside()) != null) {
            return null;
        }
        long clock = clockTicks(server);
        restockIfDue(server, clock);
        decayIfDue(clock);
        if (getOffers().isEmpty()) {
            return null;
        }
        setTradingPlayer(player);
        applyPrices(player);
        ((Merchant) body).openTradingScreen(player, body.getDisplayName(), level);
        if (tradingPlayer == player && !(player.containerMenu instanceof MerchantMenu)) {
            tradingPlayer = null; // the menu did not open (a fake player without a connection)
        }
        return InteractionResult.SUCCESS;
    }

    /**
     * A gift of the {@code reputation} gift item: taken (one from the stack, none in creative) when the mob is alive, not
     * a baby, not angry and below the gift cap; the trade sound plays and happy particles rise. Null passes the click on
     * (it then opens the menu as any other item).
     */
    private InteractionResult takeGift(ServerLevel server, Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (reputation == null || !reputation.isGift(stack)) {
            return null;
        }
        PathfinderMob body = body();
        if (!body.isAlive() || body.isBaby() || body.getTarget() != null || !reputation.gift(player.getUUID())) {
            return null;
        }
        stack.consume(1, player);
        body.playSound(getNotifyTradeSound(), 1.0f, body.getVoicePitch());
        server.sendParticles(ParticleTypes.HAPPY_VILLAGER, body.getX(), body.getY() + body.getBbHeight() + 0.3, body.getZ(), 5,
                0.3, 0.2, 0.3, 0.0);
        return InteractionResult.SUCCESS;
    }

    /** A hit by {@code player} ({@code TraderReputation}'s damage listener): the hit part of the standing grows. */
    void hurtBy(Player player) {
        if (reputation != null && body().level() instanceof ServerLevel) {
            reputation.hurt(player.getUUID());
        }
    }

    /**
     * Sets every offer's special price for {@code player}'s standing ({@code reputation}); nothing without it. Vanilla's
     * menu shows and charges the changed price; {@code #setTradingPlayer} resets it when the menu closes.
     */
    public void applyPrices(Player player) {
        if (reputation == null || offers == null || player == null) {
            return;
        }
        int value = reputation.value(player.getUUID());
        for (MerchantOffer offer : offers) {
            offer.setSpecialPriceDiff(reputation.specialPrice(value, offer));
        }
    }

    /** Fades the standings once per clock day ({@code reputation}); returns whether anything faded. */
    public boolean decayIfDue(long clockTicks) {
        return reputation != null && reputation.decayIfDue(clockTicks);
    }

    /**
     * Why the mob does not trade with {@code player} now, or null when it does (ADR 0098 D1): dead, a baby, angry (it
     * has a target), ridden, a {@code monster} at night, or trading with another player.
     */
    public String refusal(Player player, boolean night) {
        PathfinderMob body = body();
        if (!body.isAlive()) {
            return "dead";
        }
        if (body.isBaby()) {
            return "baby";
        }
        if (body.getTarget() != null) {
            return "angry";
        }
        if (body.isVehicle()) {
            return "ridden";
        }
        if (night && monster) {
            return "night";
        }
        if (tradingPlayer != null && tradingPlayer != player && stillValid(tradingPlayer)) {
            return "busy";
        }
        return null;
    }

    // Offers

    public MerchantOffers getOffers() {
        if (!(body().level() instanceof ServerLevel server)) {
            return new MerchantOffers(); // the client's menu has its own merchant
        }
        if (offers == null) {
            offers = new MerchantOffers();
            if (trader != null) {
                for (int l = 1; l <= level; l++) {
                    draw(server, l);
                }
            }
        }
        return offers;
    }

    private void draw(ServerLevel server, int forLevel) {
        if (forLevel > trader.tradeSets().size()) {
            return;
        }
        Identifier id = trader.tradeSets().get(forLevel - 1).tradeSet();
        ResourceKey<TradeSet> key = ResourceKey.create(Registries.TRADE_SET, id);
        Optional<TradeSet> set = server.registryAccess().lookupOrThrow(Registries.TRADE_SET).getOptional(key);
        if (set.isEmpty()) {
            Identifier type = BuiltInRegistries.ENTITY_TYPE.getKey(body().getType());
            if (WARNED.add(type + " " + id)) {
                LOGGER.warn("{}: msm:trader level {} names trade set {}, which is not loaded; that level has no offers",
                        type, forLevel, id);
            }
            return;
        }
        drawOffers(server, body(), set.get(), offers, null);
    }

    /**
     * Adds the offers of one draw from {@code set} to {@code out}, as a villager's: the set's number of trades, picked at
     * random (without repeats unless the set allows duplicates); a trade whose {@code getOffer} gives nothing (its
     * {@code merchant_predicate} or item filter refuses) is skipped and its id added to {@code dropped} when given.
     * Returns the number added.
     */
    public static int drawOffers(ServerLevel server, Entity self, TradeSet set, MerchantOffers out, List<String> dropped) {
        LootContext context = new LootContext.Builder(new LootParams.Builder(server)
                .withParameter(LootContextParams.ORIGIN, self.position())
                .withParameter(LootContextParams.THIS_ENTITY, self)
                .withParameter(LootContextParams.ADDITIONAL_COST_COMPONENT_ALLOWED, Unit.INSTANCE)
                .create(LootContextParamSets.VILLAGER_TRADE)).create(set.randomSequence());
        int wanted = set.calculateNumberOfTrades(context);
        List<Holder<VillagerTrade>> pool = new ArrayList<>();
        set.trades().forEach(pool::add);
        RandomSource random = context.getRandom();
        int added = 0;
        while (added < wanted && !pool.isEmpty()) {
            int i = random.nextInt(pool.size());
            Holder<VillagerTrade> trade = pool.get(i);
            MerchantOffer offer = trade.value().getOffer(context);
            if (offer == null || !set.allowDuplicates()) {
                pool.remove(i);
            }
            if (offer == null) {
                if (dropped != null) {
                    dropped.add(trade.unwrapKey().map(k -> k.identifier().toString()).orElse("(inline trade)"));
                }
                continue;
            }
            out.add(offer);
            added++;
        }
        return added;
    }

    // Trading

    public void setTradingPlayer(Player player) {
        if (player == null && reputation != null && offers != null) {
            offers.forEach(MerchantOffer::resetSpecialPriceDiff); // as a villager when trading stops
        }
        tradingPlayer = player;
    }

    public Player getTradingPlayer() {
        return tradingPlayer;
    }

    public void overrideOffers(MerchantOffers offers) {}

    public void notifyTrade(MerchantOffer offer) {
        offer.increaseUses();
        PathfinderMob body = body();
        if (!(body.level() instanceof ServerLevel server) || trader == null) {
            return;
        }
        if (offer.shouldRewardExp()) {
            ExperienceOrb.award(server, body.position().add(0, 0.5, 0), 3 + body.getRandom().nextInt(4));
        }
        Player player = tradingPlayer;
        if (reputation != null && player != null) {
            reputation.trade(player.getUUID());
        }
        if (trader.levels()) {
            xp += offer.getXp();
            boolean levelled = false;
            while (level < trader.maxLevel() && xp >= threshold(level)) {
                level++;
                levelled = true;
                draw(server, level);
            }
            if (levelled) {
                applyPrices(player); // the new level's offers, at the prices of the menu's player
                resend();
            }
        }
        if (onTrade != null) {
            onTrade.accept(server, player);
        }
    }

    /** Trading XP needed to leave {@code fromLevel}: the level's {@code xp_to_next}, else vanilla's threshold. */
    private int threshold(int fromLevel) {
        return trader.xpToLeave(fromLevel, VillagerData.getMaxXpPerLevel(fromLevel));
    }

    public void notifyTradeUpdated(ItemStack stack) {
        // The trade sound when the result slot fills, at most once a second (a shift-click gets the menu's own).
        PathfinderMob body = body();
        if (trader != null && !stack.isEmpty() && !body.level().isClientSide() && body.tickCount - lastTradeSound >= 20) {
            lastTradeSound = body.tickCount;
            body.playSound(getNotifyTradeSound(), 1.0f, body.getVoicePitch());
        }
    }

    /**
     * The XP the menu shows: the real XP scaled from this level's span into vanilla's span for the level (vanilla's
     * client draws the bar against villager thresholds), so the bar fills as the mob nears its own next level; a full
     * bar at the last level below 5. Equal to {@code #xp()} with vanilla's thresholds.
     */
    public int getVillagerXp() {
        if (trader == null || !trader.levels()) {
            return 0;
        }
        int vanillaMin = VillagerData.getMinXpPerLevel(level);
        int vanillaMax = VillagerData.getMaxXpPerLevel(level);
        if (level >= trader.maxLevel()) {
            return level >= VillagerData.MAX_VILLAGER_LEVEL ? xp : vanillaMax;
        }
        int min = level == 1 ? 0 : threshold(level - 1);
        int max = threshold(level);
        if (min == vanillaMin && max == vanillaMax) {
            return xp;
        }
        double part = max <= min ? 1.0 : Math.clamp((xp - min) / (double) (max - min), 0.0, 1.0);
        return vanillaMin + (int) Math.round(part * (vanillaMax - vanillaMin));
    }

    public void overrideXp(int xp) {}

    public boolean showProgressBar() {
        return trader != null && trader.levels();
    }

    public SoundEvent getNotifyTradeSound() {
        if (trader == null || trader.tradeSound().isEmpty()) {
            return SoundEvents.VILLAGER_YES;
        }
        return BuiltInRegistries.SOUND_EVENT.getOptional(trader.tradeSound().get()).orElse(SoundEvents.VILLAGER_YES);
    }

    public boolean canRestock() {
        return trader != null && trader.restock() == Trader.Restock.TWICE_A_DAY;
    }

    public boolean isClientSide() {
        return body().level().isClientSide();
    }

    public boolean stillValid(Player player) {
        PathfinderMob body = body();
        return tradingPlayer == player && body.isAlive() && !body.isRemoved() && body.distanceToSqr(player) <= 64.0;
    }

    /** Sends the offers again to the trading player's open menu, as villagers do after a level-up or restock. */
    private void resend() {
        if (tradingPlayer instanceof ServerPlayer player && player.containerMenu instanceof MerchantMenu menu
                && offers != null && menu.getOffers() == offers) {
            player.sendMerchantOffers(menu.containerId, offers, level, getVillagerXp(), showProgressBar(), canRestock());
            resends++;
        }
    }

    // Restocking

    /** The dimension's clock, or the Overworld's when its type names none (as {@code ScriptWorld.dayTime}, unwrapped). */
    public static long clockTicks(ServerLevel level) {
        return level.dimensionType().defaultClock().isPresent() ? level.getDefaultClockTime() : level.getOverworldClockTime();
    }

    /**
     * Refills used offers when {@code clockTicks} is in another half day than the last check ({@code twice_a_day});
     * the first check only remembers the half day. Returns whether the offers were refilled. With {@code work_site} a
     * due restock only marks the offers as waiting ({@code #restockPending}) and returns false: the work site goal
     * restocks.
     */
    public boolean restockIfDue(ServerLevel server, long clockTicks) {
        if (!canRestock()) {
            return false;
        }
        long halfDay = Math.floorDiv(clockTicks, HALF_DAY);
        if (restockHalfDay == halfDay) {
            return false;
        }
        boolean first = restockHalfDay == UNKNOWN;
        restockHalfDay = halfDay;
        if (first || offers == null || offers.stream().noneMatch(MerchantOffer::needsRestock)) {
            return false;
        }
        if (trader.workSite().isPresent()) {
            restockPending = true;
            return false;
        }
        restock();
        return true;
    }

    /** The work site goal reached the site: restocks the waiting offers. Returns whether it restocked. */
    public boolean restockAtWorkSite() {
        if (!restockPending) {
            return false;
        }
        restockPending = false;
        restock();
        return true;
    }

    /** Refills every offer, after vanilla's demand rule when {@code demand} is on (B524: demand first, then the uses). */
    private void restock() {
        for (MerchantOffer offer : offers) {
            if (trader.demand()) {
                offer.updateDemand();
            }
            offer.resetUses();
        }
        restocks++;
        resend();
    }

    /** After vanilla's {@code customServerAiStep}: a trading mob stands and looks at its customer; restocking. */
    void customServerAiStep(ServerLevel server) {
        if (trader == null) {
            return;
        }
        PathfinderMob body = body();
        if (tradingPlayer != null) {
            if (stillValid(tradingPlayer)) {
                body.getNavigation().stop();
                body.getLookControl().setLookAt(tradingPlayer, 30.0f, 30.0f);
            } else if (!(tradingPlayer.containerMenu instanceof MerchantMenu menu) || menu.getOffers() != offers) {
                tradingPlayer = null;
            }
        }
        if (workSiteGoal == null && trader.workSite().isPresent()) {
            // MobGoals runs inside the vanilla constructor; the goal joins on the first server AI step instead.
            workSiteGoal = new RestockAtWorkSiteGoal(body, this, trader.workSite().get());
            body.getGoalSelector().addGoal(workSitePriority, workSiteGoal);
        }
        if (Math.floorMod(server.getGameTime() + body.getId(), 20L) == 0) {
            long clock = clockTicks(server);
            restockIfDue(server, clock);
            decayIfDue(clock);
        }
    }

    // Saving

    /** After vanilla's {@code addAdditionalSaveData}. */
    void addAdditionalSaveData(ValueOutput output) {
        if (trader == null) {
            return;
        }
        output.storeNullable(OFFERS, MerchantOffers.CODEC, offers);
        output.putInt(XP, xp);
        output.putInt(LEVEL, level);
        if (restockHalfDay != UNKNOWN) {
            output.putLong(RESTOCK, restockHalfDay);
        }
        if (restockPending) {
            output.putBoolean(PENDING, true);
        }
        if (reputation != null) {
            reputation.save(output);
        }
    }

    /** After vanilla's {@code readAdditionalSaveData}. */
    void readAdditionalSaveData(ValueInput input) {
        if (trader == null) {
            return;
        }
        offers = input.read(OFFERS, MerchantOffers.CODEC).orElse(null);
        if (offers != null) {
            offers.forEach(MerchantOffer::resetSpecialPriceDiff); // a mob saved while trading kept that player's prices
        }
        xp = Math.max(0, input.getIntOr(XP, 0));
        level = Math.clamp(input.getIntOr(LEVEL, 1), 1, trader.maxLevel());
        restockHalfDay = input.getLongOr(RESTOCK, UNKNOWN);
        restockPending = trader.workSite().isPresent() && input.getBooleanOr(PENDING, false);
        if (reputation != null) {
            reputation.load(input);
        }
    }
}
`;
}

/** `entity/TraderReputation.java`: the runtime's `TraderReputation`. */
export function traderReputationJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's TraderReputation (registry/mob) as a plain class.
package ${entityPackage};

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.minecraft.core.UUIDUtil;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.tags.TagKey;
import net.minecraft.util.Mth;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.trading.MerchantOffer;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

/**
 * What a project trader remembers of each player (ADR 0107 D1 as amended after the B524 spike, {@code msm:trader}
 * {@code reputation}): our own per-trader, per-player standing, not vanilla's gossip, so it never spreads to other mobs
 * (limit N10). A standing has three parts, as vanilla's gossip types that B524 measured: what hits took ({@code hurt}
 * each, at most {@code #HURT_CAP}), what trades gave ({@code trade} each, at most {@code Trader.Reputation#TRADE_CAP})
 * and what gifts gave ({@code gift} each, at most {@code Trader.Reputation#GIFT_CAP}). The value is trades plus gifts
 * minus hits. Each clock day the hit part recovers {@code decay_per_day} and the trade part fades by
 * {@code Trader.Reputation#TRADE_DECAY_PER_DAY}; the gift part does not fade (as a cure's in vanilla). A standing at
 * zero is forgotten.
 *
 * <p>The value becomes each offer's special price when that player opens the menu ({@code #specialPrice}): minus the value
 * divided by {@code price_step}, rounded down, or, without {@code price_step}, minus the value times the offer's own
 * price multiplier (its {@code reputation_discount}), rounded down, which is vanilla's rule. Vanilla's menu then shows
 * {@code clamp(base + demand part + special, 1, stack size)}. The standings are saved with the mob under
 * {@code Reputation} and {@code ReputationDay}; removing {@code msm:trader} drops them, as it drops the levels.
 */
public final class TraderReputation {
    /** The most hits take, as vanilla's minor negative gossip (B524: maximum 200). */
    public static final int HURT_CAP = 200;
    /** Clock ticks in a day: hit and trade parts fade once a day. */
    public static final long DAY = 24000L;
    static final String SAVE = "Reputation";
    static final String SAVE_DAY = "ReputationDay";
    private static final long UNKNOWN = Long.MIN_VALUE;
    private static boolean listening;

    /** One player's standing: the three parts, each 0 or more. */
    public record Standing(int hurt, int trading, int gift) {
        static final Standing NONE = new Standing(0, 0, 0);

        /** Trades plus gifts minus hits. */
        public int value() {
            return trading + gift - hurt;
        }

        boolean empty() {
            return hurt == 0 && trading == 0 && gift == 0;
        }
    }

    private record Saved(UUID player, int hurt, int trading, int gift) {
        static final Codec<Saved> CODEC = RecordCodecBuilder.create(i -> i.group(
                UUIDUtil.CODEC.fieldOf("Player").forGetter(Saved::player),
                Codec.INT.optionalFieldOf("Hurt", 0).forGetter(Saved::hurt),
                Codec.INT.optionalFieldOf("Trading", 0).forGetter(Saved::trading),
                Codec.INT.optionalFieldOf("Gift", 0).forGetter(Saved::gift)).apply(i, Saved::new));
    }

    private static final Codec<List<Saved>> SAVED = Saved.CODEC.listOf();

    private final Trader.Reputation config;
    private final Optional<Identifier> giftId;
    private final Optional<TagKey<Item>> giftTag;
    private final Map<UUID, Standing> standings = new LinkedHashMap<>();
    private long day = UNKNOWN;

    TraderReputation(Trader.Reputation config) {
        this.config = config;
        String gift = config.giftItem().orElse(null);
        if (gift == null) {
            giftId = Optional.empty();
            giftTag = Optional.empty();
        } else if (gift.startsWith("#")) {
            giftId = Optional.empty();
            giftTag = Optional.of(TagKey.create(Registries.ITEM, Identifier.parse(gift.substring(1))));
        } else {
            giftId = Optional.of(Identifier.parse(gift));
            giftTag = Optional.empty();
        }
        listen();
    }

    /**
     * Hits by a player lower the standing of every project trader with {@code reputation}: Fabric's
     * {@code ServerLivingEntityEvents.AFTER_DAMAGE} (a hit that was not blocked; the attacker is the damage source's
     * entity, so a player's arrow counts). Registered once, when the first such trader is built, which is before it can be
     * hurt.
     */
    private static synchronized void listen() {
        if (listening) {
            return;
        }
        listening = true;
        ServerLivingEntityEvents.AFTER_DAMAGE.register((entity, source, baseDamage, damageTaken, blocked) -> {
            if (!blocked && entity instanceof MobTrader.Trading mob && source.getEntity() instanceof Player player && player != entity) {
                mob.mobTrader().hurtBy(player);
            }
        });
    }

    /** The definition's numbers. */
    public Trader.Reputation config() {
        return config;
    }

    /** The standing of {@code player}; all zero when the trader has none. */
    public Standing standing(UUID player) {
        return standings.getOrDefault(player, Standing.NONE);
    }

    /** The value of {@code player}: trades plus gifts minus hits. */
    public int value(UUID player) {
        return standing(player).value();
    }

    /** The players the trader remembers, for the GameTests. */
    public Map<UUID, Standing> standings() {
        return Map.copyOf(standings);
    }

    private void put(UUID player, Standing standing) {
        if (standing.empty()) {
            standings.remove(player);
        } else {
            standings.put(player, standing);
        }
    }

    /** A hit by {@code player}: the hit part grows by {@code hurt}, at most {@code #HURT_CAP}. */
    public void hurt(UUID player) {
        Standing s = standing(player);
        put(player, new Standing(Math.min(HURT_CAP, s.hurt() + config.hurt()), s.trading(), s.gift()));
    }

    /** A trade with {@code player}: the trade part grows by {@code trade}, at most the trade cap. */
    public void trade(UUID player) {
        Standing s = standing(player);
        put(player, new Standing(s.hurt(), Math.min(Trader.Reputation.TRADE_CAP, s.trading() + config.trade()), s.gift()));
    }

    /** Whether {@code stack} is the definition's gift item (never without {@code gift_item}). */
    public boolean isGift(ItemStack stack) {
        if (stack.isEmpty()) {
            return false;
        }
        if (giftId.isPresent()) {
            Optional<Item> item = BuiltInRegistries.ITEM.getOptional(giftId.get());
            return item.isPresent() && stack.is(item.get());
        }
        return giftTag.isPresent() && stack.is(giftTag.get());
    }

    /**
     * A gift from {@code player}: the gift part grows by {@code gift}, at most the gift cap. Returns false, changing
     * nothing, when the gift part is already at the cap or {@code gift} is 0.
     */
    public boolean gift(UUID player) {
        Standing s = standing(player);
        if (config.gift() <= 0 || s.gift() >= Trader.Reputation.GIFT_CAP) {
            return false;
        }
        put(player, new Standing(s.hurt(), s.trading(), Math.min(Trader.Reputation.GIFT_CAP, s.gift() + config.gift())));
        return true;
    }

    /**
     * Fades the standings when {@code clockTicks} is in a later clock day than the last check: per day passed, the hit
     * part recovers {@code decay_per_day} and the trade part fades by the trade decay. The first check, and a clock set
     * back, only remember the day. Returns whether anything faded.
     */
    public boolean decayIfDue(long clockTicks) {
        long now = Math.floorDiv(clockTicks, DAY);
        long last = day;
        day = now;
        if (last == UNKNOWN || now <= last || standings.isEmpty()) {
            return false;
        }
        long days = Math.min(now - last, 1000L);
        boolean changed = false;
        for (Map.Entry<UUID, Standing> e : new ArrayList<>(standings.entrySet())) {
            Standing s = e.getValue();
            int hurt = (int) Math.max(0L, s.hurt() - days * config.decayPerDay());
            int trading = (int) Math.max(0L, s.trading() - days * Trader.Reputation.TRADE_DECAY_PER_DAY);
            Standing faded = new Standing(hurt, trading, s.gift());
            if (!faded.equals(s)) {
                changed = true;
                put(e.getKey(), faded);
            }
        }
        return changed;
    }

    /**
     * The special price of {@code offer} for a standing of {@code value}: minus the value divided by {@code price_step},
     * rounded down, else minus the value times the offer's price multiplier, rounded down (vanilla's rule, B524).
     */
    public int specialPrice(int value, MerchantOffer offer) {
        return specialPrice(value, offer.getPriceMultiplier(), config.priceStep());
    }

    /** {@code #specialPrice(int, MerchantOffer)} for a multiplier and an optional step. */
    public static int specialPrice(int value, float priceMultiplier, Optional<Integer> priceStep) {
        if (priceStep.isPresent()) {
            return -Math.floorDiv(value, priceStep.get());
        }
        return -Mth.floor(value * priceMultiplier);
    }

    // Saving

    void save(ValueOutput output) {
        if (!standings.isEmpty()) {
            List<Saved> saved = new ArrayList<>();
            standings.forEach((player, s) -> saved.add(new Saved(player, s.hurt(), s.trading(), s.gift())));
            output.store(SAVE, SAVED, saved);
        }
        if (day != UNKNOWN) {
            output.putLong(SAVE_DAY, day);
        }
    }

    void load(ValueInput input) {
        standings.clear();
        for (Saved s : input.read(SAVE, SAVED).orElse(List.of())) {
            put(s.player(), new Standing(Math.clamp(s.hurt(), 0, HURT_CAP), Math.clamp(s.trading(), 0, Trader.Reputation.TRADE_CAP),
                    Math.clamp(s.gift(), 0, Trader.Reputation.GIFT_CAP)));
        }
        day = input.getLongOr(SAVE_DAY, UNKNOWN);
    }
}
`;
}

/** `entity/RestockAtWorkSiteGoal.java`: the runtime's `RestockAtWorkSiteGoal`. */
export function restockAtWorkSiteGoalJava(entityPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's RestockAtWorkSiteGoal (goals) as a plain class.
package ${entityPackage};

import java.util.EnumSet;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Predicate;
import net.minecraft.core.BlockPos;
import net.minecraft.core.SectionPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.core.registries.Registries;
import net.minecraft.resources.Identifier;
import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Restocking at a work site (ADR 0107 D3 as amended after the B524 spike, {@code msm:trader} {@code work_site}): when
 * the trader's restock is due ({@code MobTrader#restockPending}), it looks for the nearest block matching the work site
 * (a block id or {@code #}-prefixed block tag) within {@code Trader#WORK_SITE_RANGE} blocks, at most once
 * every {@code #SEARCH_COOLDOWN} ticks and only in loaded chunks, walks there and restocks once its centre is within
 * {@code Trader#WORK_SITE_REACH} blocks ({@code MobTrader#restockAtWorkSite}). It does not run while the
 * trader trades, fights, rides or is ridden, and gives up a site after {@code #GIVE_UP_TICKS} (it searches again later).
 * Without a site in range the offers stay used up.
 */
public class RestockAtWorkSiteGoal extends Goal {
    /** Ticks between two searches. */
    public static final int SEARCH_COOLDOWN = 40;
    /** Ticks the trader walks towards one site before giving up. */
    public static final int GIVE_UP_TICKS = 1200;
    /** Ticks between two path requests while walking. */
    static final int REPATH_TICKS = 20;
    private static final double SPEED = 1.0;
    private static final Logger LOGGER = LoggerFactory.getLogger("${modId}");
    /** Work sites already warned about, so an unknown block logs once. */
    private static final Set<String> WARNED = ConcurrentHashMap.newKeySet();

    private final PathfinderMob mob;
    private final MobTrader trader;
    private final Predicate<BlockState> site;
    private BlockPos target;
    private int nextSearch;
    private int ticks;

    public RestockAtWorkSiteGoal(PathfinderMob mob, MobTrader trader, String workSite) {
        this.mob = mob;
        this.trader = trader;
        this.site = matcher(workSite, BuiltInRegistries.ENTITY_TYPE.getKey(mob.getType()).toString());
        setFlags(EnumSet.of(Flag.MOVE));
    }

    /**
     * The blocks {@code workSite} names: a {@code #}-prefixed block tag, else a block id; an id that is not a registered
     * block matches nothing and is warned about once for {@code owner}.
     */
    public static Predicate<BlockState> matcher(String workSite, String owner) {
        if (workSite.startsWith("#")) {
            TagKey<Block> tag = TagKey.create(Registries.BLOCK, Identifier.parse(workSite.substring(1)));
            return state -> state.is(tag);
        }
        Identifier id = Identifier.parse(workSite);
        Optional<Block> block = BuiltInRegistries.BLOCK.getOptional(id);
        if (block.isEmpty()) {
            if (WARNED.add(owner + " " + id)) {
                LOGGER.warn("{}: msm:trader work_site {} is not a registered block; the trader never restocks",
                        owner, id);
            }
            return state -> false;
        }
        Block wanted = block.get();
        return state -> state.is(wanted);
    }

    /** The site the trader walks to now, or null; for the GameTests. */
    public BlockPos target() {
        return target;
    }

    @Override
    public boolean canUse() {
        if (!free() || mob.tickCount < nextSearch) {
            return false;
        }
        nextSearch = mob.tickCount + SEARCH_COOLDOWN;
        target = nearest(mob.level(), mob.blockPosition(), site);
        return target != null;
    }

    private boolean free() {
        return trader.restockPending() && trader.getTradingPlayer() == null && mob.getTarget() == null && !mob.isVehicle()
                && !mob.isPassenger() && !mob.isLeashed();
    }

    /**
     * The nearest block matching {@code site} within {@code Trader#WORK_SITE_RANGE} of {@code centre} (by
     * straight-line distance), looking only in loaded chunks; null when there is none.
     */
    public static BlockPos nearest(Level level, BlockPos centre, Predicate<BlockState> site) {
        int range = Trader.WORK_SITE_RANGE;
        int minY = Math.max(level.getMinY(), centre.getY() - range);
        int maxY = Math.min(level.getMaxY(), centre.getY() + range);
        BlockPos best = null;
        double bestDistance = (double) range * range;
        BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();
        for (int x = centre.getX() - range; x <= centre.getX() + range; x++) {
            for (int z = centre.getZ() - range; z <= centre.getZ() + range; z++) {
                if (!level.hasChunk(SectionPos.blockToSectionCoord(x), SectionPos.blockToSectionCoord(z))) {
                    continue;
                }
                for (int y = minY; y <= maxY; y++) {
                    pos.set(x, y, z);
                    double distance = pos.distSqr(centre);
                    if (distance <= bestDistance && site.test(level.getBlockState(pos))) {
                        if (best == null || distance < bestDistance) {
                            best = pos.immutable();
                            bestDistance = distance;
                        }
                    }
                }
            }
        }
        return best;
    }

    @Override
    public boolean canContinueToUse() {
        return target != null && free() && ticks < GIVE_UP_TICKS && site.test(mob.level().getBlockState(target));
    }

    @Override
    public void start() {
        ticks = 0;
        walk();
    }

    private void walk() {
        // Towards the top of the site: the path ends beside or on it (B524).
        mob.getNavigation().moveTo(target.getX() + 0.5, target.getY() + 1, target.getZ() + 0.5, SPEED);
    }

    @Override
    public void tick() {
        ticks++;
        double reach = Trader.WORK_SITE_REACH;
        if (mob.position().distanceToSqr(Vec3.atCenterOf(target)) <= reach * reach) {
            mob.getNavigation().stop();
            mob.getLookControl().setLookAt(Vec3.atCenterOf(target));
            trader.restockAtWorkSite();
            return;
        }
        if (ticks % REPATH_TICKS == 0 || mob.getNavigation().isDone()) {
            walk();
        }
    }

    @Override
    public void stop() {
        target = null;
        mob.getNavigation().stop();
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }
}
`;
}

/** `entity/MobShoulder.java`: the runtime's `MobShoulder`. */
export function mobShoulderJava(entityPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: msm_runtime's MobShoulder (registry/mob) as a plain class.
package ${entityPackage};

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import net.fabricmc.fabric.api.entity.event.v1.ServerLivingEntityEvents;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.ai.goal.GoalSelector;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.minecraft.world.phys.Vec3;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.TamableAnimal;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Shoulder pets (ADR 0098 D4 as amended after the B469 spike, {@code msm:shoulder_riding}; both shoulders since ADR 0109
 * D2 as amended after B524): a tamed {@code animal} pet with {@code msm:tameable} perches on one of its owner's
 * shoulders. It is not a passenger (a player cannot be a vehicle on the server): the perched flag
 * ({@code TamableAnimal#DATA_PERCHED}, synched and saved as {@code Perched}) and the side ({@code TamableAnimal#DATA_PERCH_LEFT},
 * synched and saved as {@code PerchSide}) make both sides put the pet at the owner's position plus
 * {@code #offset(Player, Side)} every tick, with no gravity ({@code NoGravity}, its earlier value kept in
 * {@code PerchNoGravity}), no physics and no pushing.
 *
 * <p>Sides are named by the player's own view: {@code Side#RIGHT} is the player's right (seen from behind, the side of
 * vanilla's right parrot; the only side before ADR 0109), {@code Side#LEFT} the mirror image. {@code sides} picks one,
 * or {@code either} (the default) takes the free one, the right first. A player carries at most two pets, one per side
 * (the server's {@code #PERCHED} index). Vanilla's parrots keep their own shoulders (they take the left first): a side
 * holding a parrot is not free, and every tick a perched pet moves to the side the parrots leave free (when its
 * {@code sides} allows), or gets off when there is none.
 *
 * <p>The pet gets on by its goal ({@code PerchOnOwnerGoal}: tamed, not ordered to sit, not riding or leashed, the
 * owner within {@code #START_RANGE} blocks, standing on the ground, not sneaking, sleeping, riding, swimming, flying,
 * gliding or a spectator, a free side it may take, and {@code #COOLDOWN} ticks after it last left). It leaves when
 * the owner takes damage that a shield does not block (Fabric's {@code AFTER_DAMAGE}), sneaks, sleeps, rides, swims or is in water, glides with an
 * elytra, becomes a spectator, changes dimension (the owner is no longer in the pet's level), leaves the game
 * ({@code DISCONNECT}, or no owner found) or dies, when no side is left for it, and when the pet itself rides, is
 * leashed or is no longer tamed.
 */
public final class MobShoulder {
    /**
     * The shoulder: this far to the side of the owner's body axis, in blocks: the right is {@code -x} turned by the body
     * yaw (the player's right as they see it), the left {@code +x}.
     */
    public static final double SIDE = 0.4;
    /** The shoulder: this far below the top of the owner's box (1.35 above the feet standing, lower while sneaking). */
    public static final double BELOW_TOP = 0.45;
    /** Ticks after leaving before the pet may perch again (ADR 0098 D4). */
    public static final int COOLDOWN = 100;
    /** The goal starts with the owner this near, in blocks. */
    public static final double START_RANGE = 8;
    /** The goal perches the pet this near, in blocks. */
    public static final double PERCH_REACH = 1.5;

    /** A shoulder, named by the player's own view. */
    public enum Side {
        LEFT, RIGHT;

        public Side other() {
            return this == LEFT ? RIGHT : LEFT;
        }

        public String serialName() {
            return this == LEFT ? "left" : "right";
        }
    }

    /** {@code sides}: a side named by the player's view, or whichever is free (the runtime's {@code ShoulderSide}). */
    public enum Sides {
        LEFT, RIGHT, EITHER
    }

    /** A shoulder pet as the generated entity class is one. */
    public interface Pet {
        MobShoulder shoulder();

        EntityType<?> getType();
    }

    /** The two seats of one owner (server). */
    private static final class Seats {
        volatile Pet left;
        volatile Pet right;

        Pet get(Side side) {
            return side == Side.LEFT ? left : right;
        }

        void set(Side side, Pet pet) {
            if (side == Side.LEFT) {
                left = pet;
            } else {
                right = pet;
            }
        }

        void remove(Pet pet) {
            if (left == pet) {
                left = null;
            }
            if (right == pet) {
                right = null;
            }
        }
    }

    /** Server: owner UUID to the pets perched on that owner. */
    private static final Map<UUID, Seats> PERCHED = new ConcurrentHashMap<>();
    /** Entity types already warned about an unusable component. */
    private static final Set<Identifier> WARNED = ConcurrentHashMap.newKeySet();
    private static final Logger LOGGER = LoggerFactory.getLogger("${modId}");

    private final Pet mob;
    /** The synched perched flag and side of the generated entity class. */
    private final EntityDataAccessor<Boolean> perchedData;
    private final EntityDataAccessor<Boolean> perchLeftData;
    /** The component on a tamed-capable {@code animal} body. */
    private final boolean enabled;
    /** The sides the pet may take, in the order it tries them. */
    private final List<Side> allowed;
    private int cooldown;
    private boolean noGravityBefore;

    /**
     * The perch of {@code mob}: its synched perched and left-side flags, whether it has {@code msm:tameable} (the pet
     * perches only on an {@code animal} body with it) and the {@code sides} it may take.
     */
    public MobShoulder(Pet mob, EntityDataAccessor<Boolean> perchedData, EntityDataAccessor<Boolean> perchLeftData,
            boolean tameable, Sides sides) {
        this.mob = mob;
        this.perchedData = perchedData;
        this.perchLeftData = perchLeftData;
        this.enabled = mob instanceof TamableAnimal && tameable;
        this.allowed = switch (sides) {
            case LEFT -> List.of(Side.LEFT);
            case RIGHT -> List.of(Side.RIGHT);
            case EITHER -> List.of(Side.RIGHT, Side.LEFT);
        };
        if (!enabled) {
            // The entity type's id, as the runtime logs it.
            Identifier id = BuiltInRegistries.ENTITY_TYPE.getKey(mob.getType());
            if (WARNED.add(id)) {
                LOGGER.warn("{}: msm:shoulder_riding needs base 'animal' and msm:tameable; the pet never perches",
                        id);
            }
        }
        if (enabled) {
            Listeners.ensure();
        }
    }

    /** Whether the mob can perch at all. */
    public boolean enabled() {
        return enabled;
    }

    private TamableAnimal body() {
        return (TamableAnimal) mob;
    }

    /** Whether the pet sits on its owner's shoulder now (both sides). */
    public boolean perched() {
        return enabled && body().getEntityData().get(perchedData);
    }

    /** The side the pet sits on (meaningful while {@code #perched()}; both sides read the synched flag). */
    public Side side() {
        return enabled && body().getEntityData().get(perchLeftData) ? Side.LEFT : Side.RIGHT;
    }

    /** The sides {@code sides} allows, in the order the pet tries them. */
    public List<Side> allowedSides() {
        return allowed;
    }

    /** Ticks until the pet may perch again. */
    public int cooldown() {
        return cooldown;
    }

    /** The place on the owner's right shoulder ({@code #offset(Player, Side)}), the only side before ADR 0109. */
    public static Vec3 offset(Player owner) {
        return offset(owner, Side.RIGHT);
    }

    /** The pet's place relative to the owner's feet: {@code #SIDE} to that side, {@code #BELOW_TOP} under the box's top. */
    public static Vec3 offset(Player owner, Side side) {
        double x = side == Side.RIGHT ? -SIDE : SIDE;
        return new Vec3(x, owner.getBbHeight() - BELOW_TOP, 0).yRot(-owner.yBodyRot * Mth.DEG_TO_RAD);
    }

    /** The pet perched on {@code owner}'s {@code side}, or null (server). */
    public static Pet perchedOn(Player owner, Side side) {
        Seats seats = PERCHED.get(owner.getUUID());
        if (seats == null) {
            return null;
        }
        Pet pet = seats.get(side);
        if (pet == null) {
            return null;
        }
        Entity body = (Entity) pet;
        if (body.isRemoved() || !pet.shoulder().perched() || pet.shoulder().side() != side) {
            seats.remove(pet);
            return null;
        }
        return pet;
    }

    /** A pet perched on {@code owner}, the right shoulder's first, or null (server). */
    public static Pet perchedOn(Player owner) {
        Pet right = perchedOn(owner, Side.RIGHT);
        return right != null ? right : perchedOn(owner, Side.LEFT);
    }

    /** Whether vanilla has a parrot on that shoulder of {@code owner}. */
    public static boolean parrotOn(Player owner, Side side) {
        return (side == Side.LEFT ? owner.getShoulderParrotLeft() : owner.getShoulderParrotRight()).isPresent();
    }

    /** Whether {@code side} holds neither a parrot nor another pet (server; on the client only the parrots are known). */
    private boolean free(Player owner, Side side) {
        if (parrotOn(owner, side)) {
            return false;
        }
        if (!(owner.level() instanceof ServerLevel)) {
            return true;
        }
        Pet other = perchedOn(owner, side);
        return other == null || other == mob;
    }

    /** The first side the pet may take on {@code owner} now, or null. */
    public Side freeSide(Player owner) {
        for (Side side : allowed) {
            if (free(owner, side)) {
                return side;
            }
        }
        return null;
    }

    /** Why no allowed side is free (assumes {@code #freeSide} is null). */
    private String takenReason(Player owner) {
        if (allowed.size() > 1) {
            return "both shoulders are taken";
        }
        return parrotOn(owner, allowed.getFirst()) ? "a parrot sits on that shoulder" : "another pet is on that shoulder";
    }

    /** Why the owner cannot carry a pet now, or null. */
    public static String ownerRefusal(Player owner) {
        if (!owner.isAlive()) {
            return "the owner is dead";
        }
        if (owner.isSpectator()) {
            return "the owner is a spectator";
        }
        if (owner.isShiftKeyDown()) {
            return "the owner sneaks";
        }
        if (owner.isSleeping()) {
            return "the owner sleeps";
        }
        if (owner.isPassenger()) {
            return "the owner rides";
        }
        if (owner.isInWater() || owner.isSwimming()) {
            return "the owner swims";
        }
        if (owner.isFallFlying()) {
            return "the owner glides";
        }
        return null;
    }

    /** Why the pet may not get on {@code owner} now, or null; the distance is the goal's business. */
    public String refusal(Player owner) {
        if (!enabled) {
            return "no msm:shoulder_riding on an animal with msm:tameable";
        }
        TamableAnimal pet = body();
        if (perched()) {
            return "already perched";
        }
        if (!pet.isAlive() || !pet.isTame() || !pet.isOwnedBy(owner)) {
            return "not tamed by this player";
        }
        if (pet.isOrderedToSit()) {
            return "ordered to sit";
        }
        if (pet.isPassenger() || pet.isVehicle() || pet.isLeashed()) {
            return "the pet rides, carries or is leashed";
        }
        if (cooldown > 0) {
            return "cooling down";
        }
        if (owner.level() != pet.level()) {
            return "the owner is in another dimension";
        }
        String ownerRefusal = ownerRefusal(owner);
        if (ownerRefusal != null) {
            return ownerRefusal;
        }
        if (!owner.onGround() || owner.getAbilities().flying) {
            return "the owner is not on the ground";
        }
        if (freeSide(owner) == null) {
            return takenReason(owner);
        }
        return null;
    }

    /** The goal's owner: a player that the pet may get on now and that stands within {@code #START_RANGE}, or null. */
    public Player ownerToPerchOn() {
        if (!enabled) {
            return null;
        }
        TamableAnimal pet = body();
        if (!(pet.getOwner() instanceof Player owner) || pet.distanceToSqr(owner) > START_RANGE * START_RANGE) {
            return null;
        }
        return refusal(owner) == null ? owner : null;
    }

    /** Perches the pet on {@code owner} (server); false, changing nothing, when {@code #refusal} says no. */
    public boolean perch(Player owner) {
        TamableAnimal pet = body();
        if (!(pet.level() instanceof ServerLevel) || refusal(owner) != null) {
            return false;
        }
        Side side = freeSide(owner);
        noGravityBefore = pet.isNoGravity();
        pet.getEntityData().set(perchLeftData, side == Side.LEFT);
        pet.getEntityData().set(perchedData, true);
        pet.setNoGravity(true);
        pet.noPhysics = true;
        pet.getNavigation().stop();
        pet.setTarget(null);
        PERCHED.computeIfAbsent(owner.getUUID(), u -> new Seats()).set(side, mob);
        place(pet, owner, side);
        return true;
    }

    /** Takes the pet off its owner's shoulder (server); it falls from where it sat and may not return for {@code #COOLDOWN} ticks. */
    public void unperch() {
        if (!perched()) {
            return;
        }
        TamableAnimal pet = body();
        if (!(pet.level() instanceof ServerLevel)) {
            return;
        }
        pet.getEntityData().set(perchedData, false);
        pet.setNoGravity(noGravityBefore);
        pet.noPhysics = false;
        pet.setDeltaMovement(Vec3.ZERO);
        pet.resetFallDistance();
        cooldown = COOLDOWN;
        forget(mob);
    }

    private static void forget(Pet pet) {
        for (Seats seats : PERCHED.values()) {
            seats.remove(pet);
        }
    }

    private static void place(TamableAnimal pet, Player owner, Side side) {
        Vec3 at = owner.position().add(offset(owner, side));
        pet.setPos(at.x, at.y, at.z);
        pet.setDeltaMovement(Vec3.ZERO);
        pet.setYRot(owner.yBodyRot);
        pet.yBodyRot = owner.yBodyRot;
        pet.setYHeadRot(owner.getYHeadRot());
        pet.setXRot(0);
    }

    /** Why a perched pet must leave now, or null (server). */
    private String leaveReason(TamableAnimal pet) {
        if (!(pet.getOwner() instanceof Player owner)) {
            return "the owner left";
        }
        if (owner.level() != pet.level()) {
            return "the owner changed dimension";
        }
        if (!pet.isAlive() || !pet.isTame() || pet.isPassenger() || pet.isLeashed()) {
            return "the pet cannot stay";
        }
        String ownerRefusal = ownerRefusal(owner);
        if (ownerRefusal != null) {
            return ownerRefusal;
        }
        if (freeSide(owner) == null) {
            return takenReason(owner);
        }
        return null;
    }

    /** After vanilla's {@code tick}, on both sides: the server checks and places, the client places. */
    void tick() {
        if (!enabled) {
            return;
        }
        TamableAnimal pet = body();
        if (pet.level() instanceof ServerLevel) {
            if (cooldown > 0) {
                cooldown--;
            }
            if (!perched()) {
                return;
            }
            if (leaveReason(pet) != null) {
                unperch();
                return;
            }
            Player owner = (Player) pet.getOwner();
            Side side = side();
            if (!free(owner, side)) {
                // A parrot (or, after a load, another pet) took this side: move to the side left free.
                side = freeSide(owner);
                forget(mob);
                pet.getEntityData().set(perchLeftData, side == Side.LEFT);
            }
            Seats seats = PERCHED.computeIfAbsent(owner.getUUID(), u -> new Seats());
            if (seats.get(side) == null) {
                seats.set(side, mob);
            }
            place(pet, owner, side);
        } else if (perched() && pet.getOwner() instanceof Player owner && owner.level() == pet.level()) {
            place(pet, owner, side());
        }
    }

    /** Adds {@code PerchOnOwnerGoal} after the fighting goals (where following the owner goes); called by the generated {@code registerGoals}. */
    public void addGoals(GoalSelector goalSelector, int priority, double speed) {
        if (!enabled) {
            return;
        }
        goalSelector.addGoal(priority, new PerchOnOwnerGoal(body(), this, speed));
    }

    /** No right-click of its own: a perched pet is reached through its owner's shoulder only by accident. */
    InteractionResult mobInteract(Player player, InteractionHand hand) {
        return null;
    }

    void onSyncedDataUpdated(EntityDataAccessor<?> accessor) {
        if (enabled && accessor == perchedData) {
            body().noPhysics = perched();
        }
    }

    /** A perched pet is not pushed and pushes nothing. */
    public boolean isPushable(boolean vanilla) {
        return vanilla && !perched();
    }

    public void doPush(Entity entity, Runnable vanilla) {
        if (!perched()) {
            vanilla.run();
        }
    }

    /** A perched pet's head may reach into a low ceiling over its owner; it does not suffocate there. */
    public boolean isInWall(BooleanSupplier vanilla) {
        return !perched() && vanilla.getAsBoolean();
    }

    void die() {
        unperch();
    }

    void remove(Entity.RemovalReason reason) {
        forget(mob);
    }

    void addAdditionalSaveData(ValueOutput output) {
        if (!enabled) {
            return;
        }
        boolean perched = perched();
        output.putBoolean("Perched", perched);
        if (perched) {
            output.putBoolean("PerchNoGravity", noGravityBefore);
            output.putString("PerchSide", side().serialName());
        }
        if (cooldown > 0) {
            output.putInt("ShoulderCooldown", cooldown);
        }
    }

    /** A pet saved perched stays perched only if its owner is there on its first tick (the server checks). */
    void readAdditionalSaveData(ValueInput input) {
        if (!enabled) {
            return;
        }
        boolean perched = input.getBooleanOr("Perched", false);
        noGravityBefore = input.getBooleanOr("PerchNoGravity", false);
        cooldown = Math.max(0, input.getIntOr("ShoulderCooldown", 0));
        boolean left = input.getString("PerchSide").map("left"::equals).orElse(false);
        body().getEntityData().set(perchLeftData, left && allowed.contains(Side.LEFT) || !allowed.contains(Side.RIGHT));
        body().getEntityData().set(perchedData, perched);
        body().noPhysics = perched;
    }

    /** Owner events that end a perch at once; registered when the first pet with the component is built. */
    private static final class Listeners {
        static {
            ServerLivingEntityEvents.AFTER_DAMAGE.register((entity, source, baseDamage, damage, blocked) -> {
                if (!blocked && entity instanceof Player player) {
                    leave(player);
                }
            });
            ServerPlayConnectionEvents.DISCONNECT.register((handler, server) -> leave(handler.player));
        }

        static void ensure() {
            // Loading the class registers the listeners once.
        }

        private static void leave(Player owner) {
            for (Side side : Side.values()) {
                Pet pet = perchedOn(owner, side);
                if (pet != null) {
                    pet.shoulder().unperch();
                }
            }
        }
    }
}
`;
}

/** `entity/PerchOnOwnerGoal.java`: the runtime's `PerchOnOwnerGoal`. */
export function perchOnOwnerGoalJava(entityPackage: string): string {
  return `// Generated by MCSuperMods: msm_runtime's PerchOnOwnerGoal (goals) as a plain class.
package ${entityPackage};

import java.util.EnumSet;
import net.minecraft.world.entity.TamableAnimal;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.player.Player;

/**
 * The shoulder pet's way up (ADR 0098 D4, {@code msm:shoulder_riding}): when {@code MobShoulder#ownerToPerchOn} names
 * an owner, the pet walks to it and perches once within {@code MobShoulder#PERCH_REACH}. It gives up when the owner
 * no longer allows it, moves out of twice the start range, or after {@code #GIVE_UP_TICKS}.
 */
public class PerchOnOwnerGoal extends Goal {
    /** Ticks the pet tries before giving up (it may start again at once). */
    static final int GIVE_UP_TICKS = 200;

    private final TamableAnimal pet;
    private final MobShoulder shoulder;
    private final double speed;
    private Player owner;
    private int ticks;

    public PerchOnOwnerGoal(TamableAnimal pet, MobShoulder shoulder, double speed) {
        this.pet = pet;
        this.shoulder = shoulder;
        this.speed = speed;
        setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK, Flag.JUMP));
    }

    @Override
    public boolean canUse() {
        owner = shoulder.ownerToPerchOn();
        return owner != null;
    }

    @Override
    public boolean canContinueToUse() {
        double range = MobShoulder.START_RANGE * 2;
        return owner != null && ticks < GIVE_UP_TICKS && !shoulder.perched() && shoulder.refusal(owner) == null
                && pet.distanceToSqr(owner) <= range * range;
    }

    @Override
    public void start() {
        ticks = 0;
        pet.getNavigation().moveTo(owner, speed);
    }

    @Override
    public void stop() {
        owner = null;
        pet.getNavigation().stop();
    }

    @Override
    public boolean requiresUpdateEveryTick() {
        return true;
    }

    @Override
    public void tick() {
        ticks++;
        pet.getLookControl().setLookAt(owner, 10.0f, pet.getMaxHeadXRot());
        if (pet.distanceToSqr(owner) <= MobShoulder.PERCH_REACH * MobShoulder.PERCH_REACH) {
            shoulder.perch(owner);
            return;
        }
        if (ticks % 10 == 0) {
            pet.getNavigation().moveTo(owner, speed);
        }
    }
}
`;
}
